// Folds the program's answers into parity.json: [{ id, input, x5, base }] where x5 / base is "ok" or "Custom(n)"
// as answered by the wrapper .so (x5 = rc23 34996503 md5 ae4fdd9b, base = bbaa0e7b md5 f52a302d).
// Usage: tsx test/fixtures/v22-bsl/merge-results.ts <rows.json> <res-x5.json> <res-base.json> <out parity.json>
import fs from "node:fs";

const [rowsPath, x5Path, basePath, out] = process.argv.slice(2) as [string, string, string, string];
const rows = JSON.parse(fs.readFileSync(rowsPath, "utf8")) as { id: string; input: unknown }[];
const read = (p: string): Map<string, string> =>
  new Map((JSON.parse(fs.readFileSync(p, "utf8")) as { id: string; result: string }[]).map((r) => [r.id, r.result]));
const x5 = read(x5Path);
const base = read(basePath);
const merged = rows.map((r) => {
  const a = x5.get(r.id);
  const b = base.get(r.id);
  if (a === undefined || b === undefined) throw new Error(`no program answer for ${r.id}`);
  return { id: r.id, input: r.input, x5: a, base: b };
});
fs.writeFileSync(out, JSON.stringify({
  _comment: "Band Safety Law parity rows: InitMarket sent to the real wrapper .so in LiteSVM (percolator-prog branch bsl6/initmarket-matrix, tests/bsl6_initmarket_matrix.rs). x5 = rc23 34996503 (.so md5 ae4fdd9b83cec29dfc560080b7e535dd), base = bbaa0e7b (.so md5 f52a302de809da6e47a1c7e08fd31ad9); both cargo build-sbf --features devnet, engine 2f05df8c. Generated by gen-rows.ts + merge-results.ts.",
  rows: merged,
}, null, 0));
console.log(`${merged.length} rows -> ${out}`);
